export function apiExamples(apiBase: string) {
  const base = apiBase.replace(/\/$/, "");

  return {
    curl: `curl -s ${base}`,
    js: `fetch("${base}")
  .then(res => res.json())
  .then(isVpn => {
    console.log(isVpn ? "VPN is on" : "VPN is off");
  });`,
    python: `import requests

is_vpn = requests.get("${base}").json()
print("VPN is on" if is_vpn else "VPN is off")`,
    go: `package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

func main() {
	resp, _ := http.Get("${base}")
	defer resp.Body.Close()

	var isVPN bool
	json.NewDecoder(resp.Body).Decode(&isVPN)

	if isVPN {
		fmt.Println("VPN is on")
	} else {
		fmt.Println("VPN is off")
	}
}`,
  };
}
