import { config } from '../config';

export type VpnStatus = 'checking' | 'on' | 'off' | 'error';

export async function checkVpn(): Promise<boolean> {
  const res = await fetch(config.vpnApiUrl, {
    cache: 'no-store',
    headers: { Accept: 'application/json' },
  });

  if (!res.ok) {
    throw new Error(`VPN API responded with ${res.status}`);
  }

  const data: unknown = await res.json();
  if (typeof data !== 'boolean') {
    throw new Error('Unexpected VPN API payload');
  }

  return data;
}
